class Solution {
public:
    int maxScoreSightseeingPair(vector<int>& values) {
        int bestLeft = values[0], best = INT_MIN;
        for (int j = 1; j < (int)values.size(); j++) {
            best = max(best, bestLeft + values[j] - j);
            bestLeft = max(bestLeft, values[j] + j);
        }
        return best;
    }
};
